import requests
from .exceptions import NIDDError
from .validators import (ParameterValidator, ReportParametersValidator,
                         ParameterSearchValidator)
from .translators import (ParameterTranslator, ReportParametersTranslator,
                          ParameterSearchTranslator)


def _join_segments(*segments):
    return '/'.join(map(lambda s: s.strip('/'), segments))


class NIDDRemoteAPI(object):
    """ Main class representation of NIDD Web API.

    Endpoints are represented via a set of nested attributes and their methods,
    for example "NIDDRemoteAPI.report" represents "/nidd/report", while its
    method, ".parameters" represents "/nidd/report/parameters?<...>".
    """

    def __init__(self, nidd_host):
        self._nidd_host = _join_segments(nidd_host, '/nidd')
        self.report = ReportEndpoint(self._nidd_host)
        self.parameter = ParameterEndpoint(self._nidd_host)


class NIDDEndpoint(object):
    PARAM_VALIDATOR = ParameterValidator
    PARAM_TRANSLATOR = ParameterTranslator
    ENDPOINT_URL = ''

    def __init__(self, nidd_endpoint):
        self._url = _join_segments(nidd_endpoint, self.ENDPOINT_URL)

    @classmethod
    def _check_response(cls, response):
        if not response.ok:
            msg = ("endpoint returned bad response: "
                   "\"({response.status_code}) {response.reason}\".")
            msg = msg.format(response=response)
            raise NIDDError(msg)

    @classmethod
    def _validate_args(cls, **kwargs):
        cls.PARAM_VALIDATOR.validate(**kwargs)

    @classmethod
    def _translate_parameters(cls, **kwargs):
        return cls.PARAM_TRANSLATOR.translate(**kwargs)

    @classmethod
    def _compile_params(cls, **kwargs):
        return list(kwargs.items())

    def _request(self, **kwargs):
        self._validate_args(**kwargs)
        params = self._translate_parameters(**kwargs)
        params = self._compile_params(**params)
        response = requests.get(self._url, params=params)
        self._check_response(response)
        return response.content


class ReportEndpoint(NIDDEndpoint):
    """ Class representation of report endpoint of NIDD Web API. """

    PARAM_VALIDATOR = ReportParametersValidator
    PARAM_TRANSLATOR = ReportParametersTranslator
    ENDPOINT_URL = '/Report/Parameters'

    def parameters(self, package_id, **kwargs):
        # TODO: docstring with kwargs described
        return self._request(package_id=package_id, **kwargs)


class ParameterEndpoint(NIDDEndpoint):
    PARAM_TRANSLATOR = ParameterSearchTranslator
    PARAM_VALIDATOR = ParameterSearchValidator
    ENDPOINT_URL = 'api/parameter/Search'

    def search(self, **kwargs):
        # TODO: docstring with kwargs described
        return self._request(**kwargs)
